class Solution {
public:
    int addMinimum(string word) {
        const string pat = "abc";
        int ans = 0, j = 0;
        for (char c : word) {
            while (pat[j] != c) {
                ++ans;
                j = (j + 1) % 3;
            }
            j = (j + 1) % 3;
        }
        ans += (3 - j) % 3;
        return ans;
    }
};
